import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
#include <vector>
torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    std::vector<int64_t> stride,
    std::vector<int64_t> padding,
    std::vector<int64_t> output_padding,
    std::vector<int64_t> dilation,
    int64_t groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <vector>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv_transpose3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ Wt,
    const T* __restrict__ Bs,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int Dout, int Hout, int Wout,
    int kD, int kH, int kW,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int dilD, int dilH, int dilW,
    int groups)
{
  constexpr int ICChunk = 16;
  constexpr int OC_TILE  = 4;

  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);

  const int Cin_per_group  = Cin / groups;
  const int Cout_per_group = Cout / groups;
  const int K3  = kD * kH * kW;
  const int KHW = kH * kW;

  const int tid = threadIdx.x;
  const int spatial_total = Dout * Hout * Wout;
  const int p = blockIdx.x * blockDim.x + tid;

  const int nz = blockIdx.z;
  const int n  = nz / groups;
  const int g  = nz % groups;

  const int oc_tile_idx    = blockIdx.y;
  const int oc_local_base  = oc_tile_idx * OC_TILE;
  const int ic_base        = g * Cin_per_group;
  const int oc_global_base = g * Cout_per_group + oc_local_base;

  bool p_valid = p < spatial_total;
  int od = 0, oh = 0, ow = 0;
  if (p_valid) {
    od = p / (Hout * Wout);
    int r = p - od * (Hout * Wout);
    oh = r / Wout;
    ow = r - oh * Wout;
  }

  const int64_t sXn = (int64_t)Cin * D * H * Win;
  const int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;

  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                         make_shape(Cin, D, H, Win),
                         make_stride((int64_t)D * H * Win, (int64_t)H * Win, (int64_t)Win, Int<1>{}));

  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                         make_shape(Cout, Dout, Hout, Wout),
                         make_stride((int64_t)Dout * Hout * Wout, (int64_t)Hout * Wout, (int64_t)Wout, Int<1>{}));

  auto mW = make_tensor(make_gmem_ptr(Wt),
                         make_shape(Cin, Cout_per_group, K3),
                         make_stride((int64_t)Cout_per_group * K3, (int64_t)K3, Int<1>{}));

  auto sW = make_tensor(make_smem_ptr(sW_ptr),
                         make_shape(ICChunk, OC_TILE, K3),
                         make_stride(OC_TILE * K3, K3, Int<1>{}));

  float acc[OC_TILE];
  #pragma unroll
  for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
    int oc_global = oc_global_base + oc_local;
    float bval = 0.0f;
    if (Bs != nullptr && oc_global < Cout) bval = (float)Bs[oc_global];
    acc[oc_local] = bval;
  }

  for (int chunk_start = 0; chunk_start < Cin_per_group; chunk_start += ICChunk) {
    int elems = ICChunk * OC_TILE * K3;
    for (int idx = tid; idx < elems; idx += blockDim.x) {
      int k = idx % K3;
      int rem = idx / K3;
      int oc_local = rem % OC_TILE;
      int ic_local = rem / OC_TILE;
      int ic_global = chunk_start + ic_local;
      int oc_global = oc_local_base + oc_local;
      T wval = T(0);
      if (ic_global < Cin_per_group && oc_global < Cout_per_group) {
        wval = mW(ic_base + ic_global, oc_global, k);
      }
      sW(ic_local, oc_local, k) = wval;
    }
    __syncthreads();

    if (p_valid) {
      int max_ic = ICChunk;
      if (chunk_start + ICChunk > Cin_per_group) max_ic = Cin_per_group - chunk_start;

      for (int k = 0; k < K3; ++k) {
        int kd = k / KHW;
        int rem2 = k - kd * KHW;
        int kh = rem2 / kW;
        int kw = rem2 - kh * kW;

        int td = od + padD - kd * dilD;
        if (td % strideD != 0) continue;
        int id = td / strideD;
        if (id < 0 || id >= D) continue;

        int th = oh + padH - kh * dilH;
        if (th % strideH != 0) continue;
        int ih = th / strideH;
        if (ih < 0 || ih >= H) continue;

        int tw = ow + padW - kw * dilW;
        if (tw % strideW != 0) continue;
        int iw = tw / strideW;
        if (iw < 0 || iw >= Win) continue;

        for (int ic_local = 0; ic_local < max_ic; ++ic_local) {
          int ic_global = ic_base + chunk_start + ic_local;
          float xval = (float)mX(ic_global, id, ih, iw);
          #pragma unroll
          for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
            acc[oc_local] += xval * (float)sW(ic_local, oc_local, k);
          }
        }
      }
    }
    __syncthreads();
  }

  if (p_valid) {
    #pragma unroll
    for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
      int oc_global = oc_global_base + oc_local;
      if (oc_global < Cout) {
        mY(oc_global, od, oh, ow) = static_cast<T>(acc[oc_local]);
      }
    }
  }
}

torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    std::vector<int64_t> stride,
    std::vector<int64_t> padding,
    std::vector<int64_t> output_padding,
    std::vector<int64_t> dilation,
    int64_t groups)
{
  TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "tensors must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat && weight.scalar_type() == at::kFloat,
              "only float32 supported");
  TORCH_CHECK(x.dim() == 5, "x must be [N,C,D,H,W]");
  TORCH_CHECK(weight.dim() == 5, "weight must be [Cin, Cout/groups, kD,kH,kW]");
  TORCH_CHECK(stride.size()==3 && padding.size()==3 && output_padding.size()==3 && dilation.size()==3,
              "stride/padding/output_padding/dilation must have 3 elements");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();

  int64_t N   = x_c.size(0);
  int64_t Cin = x_c.size(1);
  int64_t D   = x_c.size(2);
  int64_t H   = x_c.size(3);
  int64_t Win = x_c.size(4);

  int64_t Cout_per_group = w_c.size(1);
  int64_t kD = w_c.size(2);
  int64_t kH = w_c.size(3);
  int64_t kW = w_c.size(4);
  TORCH_CHECK(w_c.size(0) == Cin, "weight.size(0) must equal in_channels");
  int64_t Cout = Cout_per_group * groups;

  int64_t strideD = stride[0], strideH = stride[1], strideW = stride[2];
  int64_t padD = padding[0], padH = padding[1], padW = padding[2];
  int64_t opD = output_padding[0], opH = output_padding[1], opW = output_padding[2];
  int64_t dilD = dilation[0], dilH = dilation[1], dilW = dilation[2];

  int64_t Dout = (D - 1) * strideD - 2 * padD + dilD * (kD - 1) + opD + 1;
  int64_t Hout = (H - 1) * strideH - 2 * padH + dilH * (kH - 1) + opH + 1;
  int64_t Wout = (Win - 1) * strideW - 2 * padW + dilW * (kW - 1) + opW + 1;

  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "invalid output size");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.dim()==1 && b_c.size(0)==Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());

  constexpr int ICChunk = 16;
  constexpr int OC_TILE = 4;
  constexpr int THREADS = 128;

  int64_t Cout_pg = Cout / groups;
  int64_t spatial_total = Dout * Hout * Wout;

  dim3 block(THREADS);
  dim3 grid(
      (unsigned)((spatial_total + THREADS - 1) / THREADS),
      (unsigned)((Cout_pg + OC_TILE - 1) / OC_TILE),
      (unsigned)(N * groups)
  );

  int64_t K3 = kD * kH * kW;
  size_t smem_bytes = (size_t)ICChunk * OC_TILE * K3 * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv_transpose3d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)D, (int)H, (int)Win,
      (int)Cout, (int)Dout, (int)Hout, (int)Wout,
      (int)kD, (int)kH, (int)kW,
      (int)strideD, (int)strideH, (int)strideW,
      (int)padD, (int)padH, (int)padW,
      (int)dilD, (int)dilH, (int)dilW,
      (int)groups
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv_transpose3d_ext = load_inline(
    name="cute_conv_transpose3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Transposed 3D convolution with a cubic kernel, implemented via a custom
    CUDA/CuTe cooperative-tiled kernel.
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.dilation = dilation
        self.groups = groups

        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.weight = nn.Parameter(
            torch.empty(in_channels, out_channels // groups,
                        kernel_size, kernel_size, kernel_size)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv_transpose3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = init._calculate_fan_in_and_fan_out(self.weight)
            if fan_in != 0:
                bound = 1.0 / math.sqrt(fan_in)
                init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        stride3 = [self.stride, self.stride, self.stride]
        padding3 = [self.padding, self.padding, self.padding]
        output_padding3 = [self.output_padding, self.output_padding, self.output_padding]
        dilation3 = [self.dilation, self.dilation, self.dilation]

        return self._ext.conv_transpose3d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            stride3,
            padding3,
            output_padding3,
            dilation3,
            int(self.groups),
        )

